final class SportsRulesService {
 public function __construct(private PDO $db){}
 public function applyWalkover(int $matchId,int $winnerTeamId,string $reason,?int $userId):void{$m=$this->match($matchId);if(!in_array($winnerTeamId,[(int)$m['home_team_id'],(int)$m['away_team_id']],true))throw new RuntimeException('Vencedor invalido para W.O.');$r=(new RuleConfigurationService($this->db))->active((int)$m['tournament_id']);[$w,$l]=array_map('intval',explode('-',str_replace(' ','',(string)($r['points']['walkover_score']??'3-0'))));$home=$winnerTeamId===(int)$m['home_team_id']?$w:$l;$away=$winnerTeamId===(int)$m['away_team_id']?$w:$l;$this->db->prepare('UPDATE matches SET home_score=?,away_score=?,status="walkover",updated_at=NOW() WHERE id=?')->execute([$home,$away,$matchId]);$this->db->prepare('INSERT INTO match_reports(match_id,state,organizer_notes,created_at,updated_at) VALUES(?,"administrative",?,NOW(),NOW()) ON DUPLICATE KEY UPDATE organizer_notes=VALUES(organizer_notes),updated_at=NOW()')->execute([$matchId,$reason]);AuditService::record('walkover','matches',$matchId,['status'=>$m['status']],['winner_team_id'=>$winnerTeamId,'score'=>$home.'-'.$away,'reason'=>$reason]);(new StandingsService($this->db))->recalculate((int)$m['tournament_id']);}
 public function applyPenalty(int $tid,int $team,int $delta,string $type,string $reason,?int $user):int{$s=$this->db->prepare('INSERT INTO team_penalties(tournament_id,team_id,points_delta,penalty_type,reason,status,created_by,created_at,updated_at) VALUES(?,?,?,?,?,"active", ?,NOW(),NOW())');$s->execute([$tid,$team,$delta,$type,$reason,$user]);$id=(int)$this->db->lastInsertId();(new StandingsService($this->db))->recalculate($tid);AuditService::record('apply_penalty','team_penalties',$id,[],['team_id'=>$team,'points_delta'=>$delta,'type'=>$type]);return$id;}
 public function revokePenalty(int $id,string $reason,?int $user):void{$s=$this->db->prepare('SELECT * FROM team_penalties WHERE id=? AND status="active" AND deleted_at IS NULL');$s->execute([$id]);$p=$s->fetch()?:throw new RuntimeException('Punicao invalida.');$this->db->prepare('UPDATE team_penalties SET status="revoked",revoked_at=NOW(),revoked_by=?,appeal_note=?,updated_at=NOW() WHERE id=?')->execute([$user,$reason,$id]);(new StandingsService($this->db))->recalculate((int)$p['tournament_id']);AuditService::record('revoke_penalty','team_penalties',$id,$p,['reason'=>$reason]);}
 public function recordCard(int $matchId,int $teamId,?int $personId,string $type,?int $user):int{$event=(new MatchReportService($this->db))->addEvent($matchId,['team_id'=>$teamId,'person_id'=>$personId,'event_type'=>$type,'period'=>'first'],$user);$m=$this->match($matchId);$units=$type==='yellow'?1:0;$this->db->prepare('INSERT INTO discipline_ledger(tournament_id,person_id,team_id,match_id,event_id,card_type,card_units,created_at,updated_at) VALUES(?,?,?,?,?,?,?,NOW(),NOW())')->execute([$m['tournament_id'],$personId,$teamId,$matchId,$event,$type,$units]);$this->refreshSuspensions((int)$m['tournament_id']);return$event;}
 public function cancelCard(int $eventId,string $reason,?int $user):void{if(trim($reason)==='')throw new RuntimeException('Motivo obrigatório para anulação.');$s=$this->db->prepare('SELECT d.*,m.tournament_id FROM discipline_ledger d JOIN matches m ON m.id=d.match_id WHERE d.event_id=? AND d.status="active" AND d.deleted_at IS NULL');$s->execute([$eventId]);$card=$s->fetch()?:throw new RuntimeException('Cartão não encontrado.');(new MatchReportService($this->db))->cancelEvent($eventId,$reason,$user);$this->db->prepare('UPDATE discipline_ledger SET status="cancelled",updated_at=NOW() WHERE id=?')->execute([$card['id']]);AuditService::record('cancel_card','discipline_ledger',(int)$card['id'],$card,['reason'=>$reason]);$this->refreshSuspensions((int)$card['tournament_id']);}
 public function pendingPlayers(int $tid):array{$rules=(new RuleConfigurationService($this->db))->active($tid);$limit=(int)($rules['discipline']['yellow_limit']??$rules['cards']['yellow_cards_for_suspension']??3);$s=$this->db->prepare('SELECT d.person_id,p.full_name,SUM(d.card_units) yellow_cards FROM discipline_ledger d JOIN people p ON p.id=d.person_id WHERE d.tournament_id=? AND d.status="active" AND d.deleted_at IS NULL GROUP BY d.person_id,p.full_name HAVING SUM(d.card_units)=?');$s->execute([$tid,max(0,$limit-1)]);return$s->fetchAll();}
 public function cleanCards(int $tid,int $stageId,?int $user):bool{$rules=(new RuleConfigurationService($this->db))->active($tid);$cleanup=$rules['discipline']['card_cleanup']??[];if(empty($cleanup['enabled'])||(int)($cleanup['stage_id']??0)!==$stageId)return false;$key='stage-'.$stageId;$check=$this->db->prepare('SELECT id FROM card_cleanups WHERE tournament_id=? AND stage_id=? AND rule_key=?');$check->execute([$tid,$stageId,$key]);if($check->fetchColumn())return false;$this->db->beginTransaction();try{$this->db->prepare('INSERT INTO card_cleanups(tournament_id,stage_id,rule_key,executed_by,created_at) VALUES(?,?,?,?,NOW())')->execute([$tid,$stageId,$key,$user]);$this->db->prepare('UPDATE discipline_ledger SET status="cleared",updated_at=NOW() WHERE tournament_id=? AND card_type="yellow" AND status="active" AND deleted_at IS NULL')->execute([$tid]);if(empty($cleanup['preserve_suspensions']))$this->db->prepare('UPDATE suspensions SET status="revoked",updated_at=NOW() WHERE tournament_id=? AND reason="Automatic yellow cards" AND status="active"')->execute([$tid]);$this->db->commit();AuditService::record('card_cleanup','stages',$stageId,[],['tournament_id'=>$tid]);return true;}catch(\Throwable$e){$this->db->rollBack();throw$e;}}
 public function authorizeLineupException(int $matchId,int $teamId,int $personId,string $reason,int $user):void{if(trim($reason)==='')throw new RuntimeException('Justificativa obrigatória.');$this->assertLineupAllowed($matchId,$teamId,[$personId],true,$reason);$this->db->prepare('INSERT INTO match_rule_exceptions(match_id,team_id,person_id,exception_type,reason,authorized_by,created_at) VALUES(?,?,?,"lineup",?,?,NOW())')->execute([$matchId,$teamId,$personId,$reason,$user]);AuditService::record('authorize_lineup_exception','matches',$matchId,[],['team_id'=>$teamId,'person_id'=>$personId,'reason'=>$reason]);}
 public function substitute(int $matchId,int $teamId,int $out,int $in,string $period,?int $minute,?int $user):int{$m=$this->match($matchId);$rules=(new RuleConfigurationService($this->db))->active((int)$m['tournament_id']);$sub=$rules['substitutions']??[];$extra=in_array($period,['extra_first','extra_second'],true);if($extra&&empty($sub['extra_substitution_in_extra_time'])&&empty($sub['extra_time_extra']))throw new RuntimeException('Regulamento não permite substituição extra na prorrogação.');foreach([$out,$in]as$p){$q=$this->db->prepare('SELECT COUNT(*) FROM match_lineups WHERE match_id=? AND team_id=? AND person_id=? AND deleted_at IS NULL');$q->execute([$matchId,$teamId,$p]);if(!$q->fetchColumn())throw new RuntimeException('Atleta não está relacionado pela equipe.');}$used=$this->db->prepare('SELECT COUNT(*) FROM match_substitutions WHERE match_id=? AND team_id=? AND deleted_at IS NULL');$used->execute([$matchId,$teamId]);$limit=(int)($sub['max_used']??5)+($extra?1:0);if((int)$used->fetchColumn()>=$limit)throw new RuntimeException('Limite de substituições atingido.');$windows=(int)($sub['max_opportunities']??$sub['windows']??3);$window=(int)$this->scalar('SELECT COALESCE(MAX(window_number),0)+1 FROM match_substitutions WHERE match_id=? AND team_id=? AND period=? AND deleted_at IS NULL',[$matchId,$teamId,$period]);if(!$extra&&$window>$windows)throw new RuntimeException('Limite de janelas atingido.');$this->db->prepare('INSERT INTO match_substitutions(match_id,team_id,player_out_id,player_in_id,period,minute,window_number,is_extra_time,created_by,created_at) VALUES(?,?,?,?,?,?,?,?,?,NOW())')->execute([$matchId,$teamId,$out,$in,$period,$minute,$window,$extra?1:0,$user]);$id=(int)$this->db->lastInsertId();AuditService::record('substitution','match_substitutions',$id,[],['match_id'=>$matchId]);return$id;}
 public function startExtraTime(int $matchId):void{$m=$this->match($matchId);$rules=(new RuleConfigurationService($this->db))->active((int)$m['tournament_id']);if(empty($rules['knockout']['extra_time'])&&!($rules['knockout']['stages']['quarterfinal']['extra_time']??false))throw new RuntimeException('Regulamento não habilita prorrogação.');if((int)$m['home_score']!==(int)$m['away_score'])throw new RuntimeException('Prorrogação requer empate.');$this->db->prepare('UPDATE matches SET status="extra_time",updated_at=NOW() WHERE id=?')->execute([$matchId]);AuditService::record('start_extra_time','matches',$matchId,['status'=>$m['status']],['status'=>'extra_time']);}
 public function recordShootout(int $matchId,int $teamId,?int $personId,string $result,?int $user):array{$m=$this->match($matchId);if(!in_array($result,['goal','saved','missed','post','invalidated'],true))throw new RuntimeException('Resultado de pênalti inválido.');if((int)$m['home_score']!==(int)$m['away_score'])throw new RuntimeException('Disputa exige empate.');if(!in_array($teamId,[(int)$m['home_team_id'],(int)$m['away_team_id']],true))throw new RuntimeException('Equipe inválida.');$rules=(new RuleConfigurationService($this->db))->active((int)$m['tournament_id']);$initial=(int)($rules['knockout']['penalty_kicks']??$rules['knockout']['stages']['quarterfinal']['penalty_kicks']??5);$count=(int)$this->scalar('SELECT COUNT(*) FROM match_shootout_attempts WHERE match_id=? AND team_id=? AND deleted_at IS NULL',[$matchId,$teamId])+1;$round=max($count,(int)$this->scalar('SELECT COUNT(*) FROM match_shootout_attempts WHERE match_id=? AND team_id<>? AND deleted_at IS NULL',[$matchId,$teamId]));$sudden=$count>$initial;$this->db->prepare('INSERT INTO match_shootout_attempts(match_id,team_id,person_id,attempt_number,round_number,result,is_sudden_death,is_valid,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,1,?,NOW(),NOW())')->execute([$matchId,$teamId,$personId,$count,$round,$result,$sudden?1:0,$user]);$score=$this->shootoutScore($matchId);$winner=$this->shootoutWinner($matchId,$initial,$score);if($winner){$this->db->prepare('UPDATE matches SET home_penalties=?,away_penalties=?,status="awaiting_homologation",updated_at=NOW() WHERE id=?')->execute([$score['home'],$score['away'],$matchId]);}AuditService::record('shootout_attempt','matches',$matchId,[],['team_id'=>$teamId,'result'=>$result,'winner'=>$winner]);return['score'=>$score,'winner_team_id'=>$winner];}
 public function refreshSuspensions(int $tid):void{$rules=(new RuleConfigurationService($this->db))->active($tid);$limit=(int)($rules['discipline']['yellow_limit']??3);$red=(int)($rules['discipline']['red_suspension']??1);$q=$this->db->prepare('SELECT person_id,SUM(card_units) yellows,MAX(card_type IN ("red","second_yellow")) sent FROM discipline_ledger WHERE tournament_id=? AND status="active" AND deleted_at IS NULL AND person_id IS NOT NULL GROUP BY person_id');$q->execute([$tid]);foreach($q as $row){$needed=(int)$row['sent']?$red:((int)$row['yellows']>=$limit?1:0);if(!$needed)continue;$exists=$this->db->prepare('SELECT id FROM suspensions WHERE tournament_id=? AND person_id=? AND status="active" AND deleted_at IS NULL LIMIT 1');$exists->execute([$tid,$row['person_id']]);if(!$exists->fetchColumn())$this->db->prepare('INSERT INTO suspensions(tournament_id,person_id,reason,matches_total,matches_served,status,created_at,updated_at) VALUES(?,?,?, ?,0,"active",NOW(),NOW())')->execute([$tid,$row['person_id'],(int)$row['sent']?'Automatic red card':'Automatic yellow cards',$needed]);}}
 public function serveSuspensions(int $matchId):void{$m=$this->match($matchId);$q=$this->db->prepare('SELECT s.id FROM suspensions s JOIN registrations r ON r.person_id=s.person_id AND r.tournament_id=s.tournament_id WHERE s.tournament_id=? AND s.status="active" AND s.matches_served<s.matches_total AND s.deleted_at IS NULL AND r.team_id IN (?,?)');$q->execute([$m['tournament_id'],$m['home_team_id'],$m['away_team_id']]);foreach($q->fetchAll(PDO::FETCH_COLUMN) as $id){$this->db->prepare('INSERT IGNORE INTO suspension_fulfillments(suspension_id,match_id,served_at,created_at) VALUES(?,?,NOW(),NOW())')->execute([$id,$matchId]);$this->db->prepare('UPDATE suspensions SET matches_served=(SELECT COUNT(*) FROM suspension_fulfillments WHERE suspension_id=?),status=IF(matches_served+1>=matches_total,"served","active"),updated_at=NOW() WHERE id=?')->execute([$id,$id]);}}
 public function assertLineupAllowed(int $matchId,int $teamId,array $people,bool $exception=false,string $reason=''):void{foreach($people as $id){$s=$this->db->prepare('SELECT COUNT(*) FROM suspensions WHERE tournament_id=(SELECT tournament_id FROM matches WHERE id=?) AND person_id=? AND status="active" AND matches_served<matches_total AND deleted_at IS NULL');$s->execute([$matchId,$id]);if($s->fetchColumn()&&!$exception)throw new RuntimeException('Atleta suspenso.');if($s->fetchColumn()&&$exception&&trim($reason)==='')throw new RuntimeException('Justificativa obrigatoria para excecao.');}}
 private function match(int $id):array{$s=$this->db->prepare('SELECT * FROM matches WHERE id=? AND deleted_at IS NULL');$s->execute([$id]);return$s->fetch()?:throw new RuntimeException('Partida nao encontrada.');}
 private function scalar(string $sql,array $p=[]):int{$s=$this->db->prepare($sql);$s->execute($p);return(int)$s->fetchColumn();}
 private function shootoutScore(int $matchId):array{$s=$this->db->prepare('SELECT team_id,SUM(result="goal") goals FROM match_shootout_attempts WHERE match_id=? AND is_valid=1 AND deleted_at IS NULL GROUP BY team_id');$s->execute([$matchId]);$m=$this->match($matchId);$out=['home'=>0,'away'=>0];foreach($s as$r)$out[(int)$r['team_id']===(int)$m['home_team_id']?'home':'away']=(int)$r['goals'];return$out;}
 private function shootoutWinner(int $matchId,int $initial,array $score):?int{$m=$this->match($matchId);$q=$this->db->prepare('SELECT team_id,COUNT(*) attempts FROM match_shootout_attempts WHERE match_id=? AND is_valid=1 AND deleted_at IS NULL GROUP BY team_id');$q->execute([$matchId]);$counts=[];foreach($q as$r)$counts[(int)$r['team_id']]=(int)$r['attempts'];$h=(int)$m['home_team_id'];$a=(int)$m['away_team_id'];if(($counts[$h]??0)>=$initial&&($counts[$a]??0)>=$initial&&($counts[$h]??0)===$counts[$a]&&$score['home']!==$score['away'])return$score['home']>$score['away']?$h:$a;return null;}
}
